	sealed class QuotedPrintableDecoderTest : TestCase
	{
		public void TestDecode()
		{
			string decodedText = new QuotedPrintableDecoder().Decode(SampleText);
			AssertEquals("DecodedText", ExpectedDecodedText, decodedText);
			string decodedText2 = new QuotedPrintableDecoder().Decode(SampleText2);
			AssertEquals("DecodedText", ExpectedDecodedText2, decodedText2);
		}

